    private static func decode(_ value: String) -> NSImage {
        guard let data = Data(base64Encoded: value, options: .ignoreUnknownCharacters),
              let image = NSImage(data: data) else {
            return NSImage(size: NSSize(width: 1, height: 1))
        }
        image.isTemplate = false
        return image
    }

    static let offline = decode(offlineBase64)
    static let connecting = decode(connectingBase64)
    static let syncing = decode(syncingBase64)
    static let thinking = decode(thinkingBase64)
    static let waiting = decode(waitingBase64)
    static let error = decode(errorBase64)

    static func image(for state: MascotState) -> NSImage {
        switch state {
        case .offline: offline
        case .connecting: connecting
        case .syncing: syncing
        case .thinking: thinking
        case .waiting: waiting
        case .error: error
        }
    }
}

func polishedMascotAccessibilityLabel(for state: MascotState) -> String {
    switch state {
    case .offline: "Отключён"
    case .connecting: "Подключается"
    case .syncing: "Синхронизирует"
    case .thinking: "Думает"
    case .waiting: "Ждёт ввода"
    case .error: "Ошибка"
    }
}

struct PolishedMascotArtwork: View {
    let state: MascotState
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @State private var breathe = false
    @State private var hovered = false

    var body: some View {
        Image(nsImage: PolishedMascotAssets.image(for: state))
            .resizable()
            .interpolation(.none)
            .aspectRatio(contentMode: .fit)
            .scaleEffect(hovered ? 1.045 : (breathe ? 1.018 : 1.0))
            .offset(y: reduceMotion ? 0 : (breathe ? -1.2 : 0.8))
            .shadow(color: .black.opacity(0.18), radius: 5, y: 3)
            .onHover { hovered = $0 }
            .onAppear {
                guard !reduceMotion else { return }
                withAnimation(.easeInOut(duration: 1.8).repeatForever(autoreverses: true)) { breathe = true }
            }
            .animation(.easeOut(duration: 0.14), value: hovered)
            .animation(.easeInOut(duration: 0.18), value: state)
            .accessibilityHidden(true)
    }
}
